<?php require_once 'includes/config.php'; require_login(); $pdo=db();$u=user();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$st=$pdo->prepare('INSERT INTO support_tickets(user_id,subject,message) VALUES(?,?,?)');$st->execute([$u['id'],post_str('subject'),post_str('message')]);flash('success','Support request submitted.');redirect('support.php');}$st=$pdo->prepare('SELECT * FROM support_tickets WHERE user_id=? ORDER BY created_at DESC');$st->execute([$u['id']]);$tickets=$st->fetchAll();$title='Support';require 'includes/header.php'; ?><div class="row g-4"><div class="col-lg-5"><div class="panel p-4"><span class="eyebrow">SUPPORT</span><h1>How can we help?</h1><p class="text-secondary">Create a support request for orders, accounts, products or returns.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input class="form-control mb-2" name="subject" placeholder="Subject" required><textarea class="form-control mb-3" name="message" rows="5" placeholder="Describe your issue" required></textarea><button class="btn btn-purple">Submit request</button></form></div></div><div class="col-lg-7"><h3>My requests</h3><?php foreach($tickets as $t):?><div class="panel p-3 mb-2"><div class="d-flex justify-content-between"><strong>#<?=$t['id']?> <?=e($t['subject'])?></strong><span class="badge bg-secondary"><?=e($t['status'])?></span></div><p class="mt-2 mb-1 text-secondary"><?=e($t['message'])?></p><?php if($t['staff_reply']):?><div class="hero-mini mt-2"><strong>Staff reply</strong><p class="mb-0"><?=e($t['staff_reply'])?></p></div><?php endif;?></div><?php endforeach;?><?php if(!$tickets):?><p class="text-secondary">No support requests yet.</p><?php endif;?></div></div><?php require 'includes/footer.php'; ?>